import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  buildCatalog,
  type Catalog,
  type CatalogSources,
  EXCLUDED_REASON,
  type Registry,
  rivalsOf,
  routeOf,
} from './catalog';

function read<T>(path: string): T {
  return JSON.parse(readFileSync(new URL(path, import.meta.url), 'utf8'));
}

// Generated by `bun run generate`, which `bun run test` runs first.
const catalog = read<Catalog>('../../dist/js-tools.json');
const generated = read<Record<string, { method: string; path: string }>>(
  '../../dist/operations.json'
);
const registry = read<Registry>(
  '../../../../crates/agent_permission_registry/registry.json'
);

describe('JS tools catalog', () => {
  it('registers exactly the operations a program can call', () => {
    const callable = new Set(
      catalog.tools.map((tool) => `${tool.service}.${tool.operationId}`)
    );
    const registered = Object.entries(registry.operations).flatMap(
      ([service, operations]) =>
        Object.keys(operations).map((operation) => `${service}.${operation}`)
    );
    expect(registered.filter((key) => !callable.has(key))).toEqual([]);
    expect([...callable].filter((key) => !registered.includes(key))).toEqual(
      []
    );
  });

  it('names each tool once, as a plain identifier path', () => {
    const paths = catalog.tools.map((tool) => tool.path.join('.'));
    expect(new Set(paths).size).toBe(paths.length);
    for (const [service, name] of catalog.tools.map((tool) => tool.path)) {
      expect(service).toMatch(/^[a-z_]+$/);
      expect(name).toMatch(/^[A-Za-z_$][A-Za-z0-9_$]*$/);
    }
  });

  it('sends each tool where its generated SDK method does', () => {
    for (const tool of catalog.tools) {
      const operation = generated[`${tool.service}.${tool.method}`];
      expect(
        operation && [operation.method, routeOf(operation.path)],
        `${tool.service}.${tool.method}`
      ).toEqual([tool.httpMethod, tool.route]);
    }
  });

  it('skips what the TypeScript SDK excludes, such as person-only routes', () => {
    const permissions = catalog.skipped.filter(
      (skip) =>
        skip.service === 'agent-harness' &&
        skip.operationId.includes('tool_permission')
    );
    expect(permissions.map((skip) => skip.operationId)).toEqual([
      'get_agent_tool_permission_policy',
      'get_agent_tool_permission_sources',
      'set_agent_tool_permissions',
      'reset_agent_tool_permissions',
      'detach_agent_tool_permissions',
      'set_agent_tool_permissions_source',
    ]);
    expect(permissions.every((skip) => skip.reason === EXCLUDED_REASON)).toBe(
      true
    );
  });

  it('otherwise skips only what a tool cannot send or read', () => {
    expect(
      catalog.skipped
        .filter((skip) => skip.reason !== EXCLUDED_REASON)
        .map((skip) => `${skip.service}.${skip.operationId}: ${skip.reason}`)
    ).toMatchInlineSnapshot(`
      [
        "connection.batch_send_message_handler: the TypeScript SDK has no client for this service",
        "connection.broadcast_message_handler: the TypeScript SDK has no client for this service",
        "connection.send_message_handler: the TypeScript SDK has no client for this service",
        "connection.get_entity_handler: the TypeScript SDK has no client for this service",
        "email.get_message_eml: its response is message/rfc822",
        "static-files.put_presigned_url: the TypeScript SDK has no client for this service",
        "static-files.handle_bulk_delete_file: the TypeScript SDK has no client for this service",
        "static-files.handle_get_metadata: the TypeScript SDK has no client for this service",
        "static-files.handle_delete_file: the TypeScript SDK has no client for this service",
        "static-files.get_file_documentation: the TypeScript SDK has no client for this service",
        "storage.event_ics: its response is text/calendar",
        "storage.get_call_recording: its response is video/mp4",
        "storage.upload_file: its request body is application/octet-stream",
        "storage.external_chat_upload: its request body is multipart/form-data",
        "storage.passwords_agent_search: needs the header parameter X-Macro-Agent-Session-Id",
        "storage.passwords_agent_create: needs the header parameter X-Macro-Agent-Session-Id",
        "storage.passwords_agent_update: needs the header parameter X-Macro-Agent-Session-Id",
        "storage.passwords_agent_request_access: needs the header parameter X-Macro-Agent-Session-Id",
        "storage.passwords_agent_my_request: needs the header parameter X-Macro-Agent-Session-Id",
        "storage.passwords_agent_disclose: needs the header parameter X-Macro-Agent-Session-Id",
        "storage.passwords_agent_set_totp: needs the header parameter X-Macro-Agent-Session-Id",
        "storage.passwords_agent_totp_code: needs the header parameter X-Macro-Agent-Session-Id",
        "storage.stream_events: its response is text/event-stream",
      ]
    `);
  });

  it('describes a tool by its permission group, action and label', () => {
    expect(
      catalog.tools.find(
        (tool) => tool.path.join('.') === 'storage.create_task_handler'
      )?.description
    ).toMatch(/^Tasks · create · Create task\. /);
  });
});

describe('rivalsOf', () => {
  const routes = [
    { service: 'storage', method: 'GET', route: '/documents/{}' },
    { service: 'storage', method: 'GET', route: '/documents/system_skills' },
    { service: 'storage', method: 'POST', route: '/documents/system_skills' },
    { service: 'storage', method: 'GET', route: '/documents/{}/markdown' },
    { service: 'storage', method: 'GET', route: '/projects/{}' },
    { service: 'email', method: 'GET', route: '/documents/{}' },
    { service: 'email', method: 'GET', route: '/{}/{}' },
  ];

  it('lists same-method routes of the same length whose literals agree', () => {
    expect(
      rivalsOf(
        { service: 'storage', method: 'GET', route: '/documents/{}' },
        routes
      )
    ).toEqual([
      { service: 'email', route: '/documents/{}' },
      { service: 'email', route: '/{}/{}' },
      { service: 'storage', route: '/documents/system_skills' },
    ]);
  });

  it('lists none for a route nothing else can match', () => {
    expect(
      rivalsOf(
        { service: 'storage', method: 'GET', route: '/documents/{}/markdown' },
        routes
      )
    ).toEqual([]);
  });
});

describe('buildCatalog', () => {
  const sources: CatalogSources = {
    specs: {
      storage: {
        paths: {
          '/documents/{document_id}': {
            parameters: [
              {
                name: 'document_id',
                in: 'path',
                required: true,
                schema: { type: 'string' },
              },
            ],
            get: {
              operationId: 'get_document',
              summary: 'Read a document.',
              parameters: [
                { name: 'full', in: 'query', schema: { type: 'boolean' } },
              ],
              responses: {
                '200': {
                  content: {
                    'application/json': {
                      schema: { $ref: '#/components/schemas/Document' },
                    },
                  },
                },
              },
            },
          },
          '/documents/v2/{document_id}': {
            get: {
              operationId: 'get_document',
              parameters: [
                {
                  name: 'document_id',
                  in: 'path',
                  required: true,
                  schema: { type: 'string' },
                },
              ],
              responses: { '204': {} },
            },
          },
          '/documents/upload': {
            post: {
              operationId: 'upload',
              requestBody: { content: { 'multipart/form-data': {} } },
              responses: { '200': {} },
            },
          },
          '/vault': {
            post: {
              operationId: 'open_vault',
              parameters: [{ name: 'X-Vault', in: 'header', required: true }],
              responses: { '200': {} },
            },
          },
        },
        components: { schemas: { Document: { type: 'object' } } },
      },
      connection: {
        paths: {
          '/connect': { get: { operationId: 'connect', responses: {} } },
        },
      },
    },
    generated: {
      'storage.getDocument': {
        method: 'GET',
        path: '/documents/{document_id}',
      },
      'storage.getDocument2': {
        method: 'GET',
        path: '/documents/v2/{document_id}',
      },
    },
    clients: { storage: 'storage' },
    verbs: { 'storage.getDocument': 'read' },
    excluded: { storage: [] },
    registry: {
      groups: [{ id: 'documents', name: 'Documents & projects' }],
      operations: {
        storage: {
          get_document: {
            group: 'documents',
            action: 'read',
            label: 'Read document',
          },
        },
      },
    },
  };

  it('builds tools, skips what they cannot send, and rewrites refs into the service defs', () => {
    expect(buildCatalog(sources)).toEqual({
      tools: [
        {
          path: ['storage', 'get_document'],
          service: 'storage',
          operationId: 'get_document',
          client: 'storage',
          method: 'getDocument',
          verb: 'read',
          httpMethod: 'GET',
          route: '/documents/{}',
          rivals: [],
          description:
            'Documents & projects · read · Read document. Read a document.',
          input: {
            type: 'object',
            properties: {
              path: {
                type: 'object',
                properties: { document_id: { type: 'string' } },
                required: ['document_id'],
                additionalProperties: false,
              },
              query: {
                type: 'object',
                properties: { full: { type: 'boolean' } },
                additionalProperties: false,
              },
            },
            required: ['path'],
            additionalProperties: false,
          },
          output: { $ref: '#/$defs/Document' },
        },
        {
          path: ['storage', 'get_document_2'],
          service: 'storage',
          operationId: 'get_document',
          client: 'storage',
          method: 'getDocument2',
          httpMethod: 'GET',
          route: '/documents/v2/{}',
          rivals: [],
          description: 'Documents & projects · read · Read document',
          input: {
            type: 'object',
            properties: {
              path: {
                type: 'object',
                properties: { document_id: { type: 'string' } },
                required: ['document_id'],
                additionalProperties: false,
              },
            },
            required: ['path'],
            additionalProperties: false,
          },
        },
      ],
      defs: { storage: { Document: { type: 'object' } } },
      skipped: [
        {
          service: 'connection',
          operationId: 'connect',
          reason: 'the TypeScript SDK has no client for this service',
        },
        {
          service: 'storage',
          operationId: 'upload',
          reason: 'its request body is multipart/form-data',
        },
        {
          service: 'storage',
          operationId: 'open_vault',
          reason: 'needs the header parameter X-Vault',
        },
      ],
    });
  });

  it('skips what the TypeScript SDK excludes, with that as the reason', () => {
    const catalog = buildCatalog({
      ...sources,
      excluded: { storage: ['getDocument2'] },
    });
    expect(catalog.tools.map((tool) => tool.path.join('.'))).toEqual([
      'storage.get_document',
    ]);
    expect(catalog.skipped[1]).toEqual({
      service: 'storage',
      operationId: 'get_document',
      reason: EXCLUDED_REASON,
    });
  });

  it('refuses an operation missing from the permission registry', () => {
    expect(() =>
      buildCatalog({
        ...sources,
        registry: { groups: sources.registry.groups, operations: {} },
      })
    ).toThrow('storage.get_document is missing from the permission registry');
  });
});
